(function(root){'use strict';
const S=root.MT_EDUCATION_MODEL_SCHEMAS;
const n=(key,label,unit,value,min,max,extra={})=>({key,label,unit,value,min,max,...extra}),s=(key,label,value,options,extra={})=>({key,label,value,options,...extra}),count=(key,label,value,min,max)=>s(key,label,value,Array.from({length:max-min+1},(_,i)=>[String(i+min),String(i+min)]),{numeric:true}),live=(key,i,max)=>({whenAny:Array.from({length:max-i+1},(_,j)=>({[key]:String(i+j)}))});
function schema(id,fn,title,chapter,description,fields,notes){S[id]={fn,title,chapter,description,fields,notes};}
const forces=[count('count','Active forces','3',1,6),n('ox','Moment origin east / x','m',0,-100,100),n('oy','Moment origin up / y','m',0,-100,100),n('couple','Applied counterclockwise couple','kN·m',0,-1e5,1e5)];for(let i=1;i<=6;i++){const extra={group:'Force '+i,...live('count',i,6)};forces.push(n('force'+i,'Force magnitude','kN',i===1?10:i===2?8:5,0,1e5,extra),n('angle'+i,'Angle counterclockwise from +x','°',i===1?90:i===2?210:330,-360,360,extra),n('x'+i,'Application x','m',i-1,-100,100,extra),n('y'+i,'Application y','m',0,-100,100,extra));}
schema('force-diagram','forceDiagram','Free-body forces and equilibrium',3,'Place forces and a couple, move the moment origin and compare force and moment balance.',forces,['Two-dimensional rigid-body statics, with +x to the right, +y upward and counterclockwise moments positive. Force angles are counterclockwise from +x.','Moment about O is Σ[(x−xO)Fy−(y−yO)Fx] plus the entered free couple. A force resultant and an independent couple are required in the general case.','The balancing force at the chosen origin is −R, with balancing couple −MO. This does not identify actual support reactions or structural capacity.']);
const truss=[count('nodes','Active joints','3',3,6),count('members','Active members','3',3,12),n('pin','Pinned joint number','',1,1,6),n('roller','Vertical roller joint number','',2,1,6),n('E','Young modulus','GPa',200,.1,500),n('area','Common member area','mm²',500,1,100000)];for(let i=1;i<=6;i++){const extra={group:'Joint '+i,...live('nodes',Math.max(3,i),6)};truss.push(n('x'+i,'East / x coordinate','m',[0,4,2,6,8,10][i-1],-100,100,extra),n('y'+i,'Up / y coordinate','m',i<=2?0:3,-100,100,extra),n('fx'+i,'Applied horizontal force','kN',0,-1000,1000,extra),n('fy'+i,'Applied vertical force','kN',i===3?-10:0,-1000,1000,extra));}for(let i=1;i<=12;i++){const pair=[[1,2],[1,3],[2,3],[2,4],[3,4],[3,5],[4,5],[4,6],[5,6],[1,4],[2,5],[3,6]][i-1],extra={group:'Member '+i,...live('members',Math.max(3,i),12)};truss.push(n('a'+i,'First joint number','',pair[0],1,6,extra),n('b'+i,'Second joint number','',pair[1],1,6,extra));}
schema('truss','truss','Plane truss builder',3,'Connect joints, choose supports and loads, then inspect axial member forces and joint movement.',truss,['Pin-jointed straight axial members with common EA, small displacements and linear elasticity. Members have no bending stiffness, self-weight or thermal strain.','The pinned joint restrains x and y; the second support restrains y only. Unconnected joints, duplicate members and mechanisms are rejected. Crossing bars are connected only at an explicitly shared joint.','The direct-stiffness equations Ku=F are solved on free degrees of freedom. Member force EAΔL/L is positive in tension. Reactions include only constrained degrees of freedom.','This is an elastic teaching model, without member buckling, joint strength, material yielding or a structural acceptance check.']);
schema('buckling','buckling','Euler column buckling',3,'Change length, end restraint and section properties to investigate elastic column instability.',[n('E','Young modulus','GPa',200,.1,500),n('inertia','Second moment about buckling axis','cm⁴',500,.001,1e8),n('area','Cross-sectional area','mm²',3000,1,1e6),n('length','Unsupported length','m',5,.01,100),s('factor','Effective-length factor','1',[['.5','0.5 · fixed–fixed ideal'],['.7','0.7 · fixed–pinned approximation'],['1','1.0 · pinned–pinned'],['2','2.0 · fixed–free ideal']],{numeric:true}),n('load','Entered compressive load','kN',100,0,1e6),n('proportional','Supplied proportional-limit stress','MPa',200,1,2000)],['Euler Pcr=π²EI/(KL)² is an ideal elastic bifurcation load for a slender straight prismatic member with axial concentric load.','Effective length factors describe idealised end restraints. The fixed–pinned value 0.7 is an approximation. Initial crookedness, eccentricity, residual stress and connection compliance are excluded.','The displayed proportional-limit comparison checks one necessary elastic applicability condition. Neither Euler load nor its entered-load ratio is an allowable design load or safety factor.']);
schema('thermal-expansion','thermalExpansion','Thermal expansion and restraint',3,'Compare free movement with partial or complete axial restraint during a uniform temperature change.',[n('E','Young modulus','GPa',200,.1,500),n('alpha','Expansion coefficient','µm/(m·K)',12,.01,100),n('length','Original length','m',2,.001,100),n('area','Cross-sectional area','mm²',1000,.01,1e6),n('delta','Uniform temperature change','K',50,-300,500),n('restraint','Restrained fraction of free movement','fraction',1,0,1)],['Uniform temperature change, constant E and thermal expansion coefficient, small strain and axial linear elasticity.','Free strain is αΔT. The entered restrained fraction r specifies an imposed displacement: actual strain=(1−r)αΔT and stress=−ErαΔT.','Positive stress and force mean tension. Heating under restraint produces compression. The restraint fraction is a displacement condition, not a measured support-spring stiffness. Temperature-dependent properties, bending, yielding and buckling are excluded.']);
const pipes=[s('mode','Arrangement','parallel',[['parallel','Common pipe feeding two parallel branches'],['series','Three consecutive pipes in series']]),n('head','Available pressure head','m',10,.001,500),n('density','Fluid density','kg/m³',1000,500,2000)];for(let i=0;i<3;i++)pipes.push(n('length'+i,'Pipe length','m',[20,30,50][i],0,10000,{group:i===0?'Common / first pipe':'Branch / pipe '+i}),n('diameter'+i,'Internal diameter','mm',[100,80,60][i],5,2000,{group:i===0?'Common / first pipe':'Branch / pipe '+i}),n('friction'+i,'Supplied Darcy friction factor','',.02,.005,.2,{group:i===0?'Common / first pipe':'Branch / pipe '+i}),n('minor'+i,'Sum of minor-loss coefficients','',[2,2,3][i],0,10000,{group:i===0?'Common / first pipe':'Branch / pipe '+i}));
schema('pipe-network','pipeNetwork','Series and parallel pipe network',11,'Combine pipe resistances and valve losses, and compare branch flow and pressure-head balance.',pipes,['Steady incompressible forward flow between common upstream and downstream pressure levels, no elevation difference or branch withdrawal.','Each segment has hL=(fL/D+ΣK)v²/(2g). Enter the Darcy friction factor, not the Fanning factor. The supplied factors are held constant as flow changes.','Parallel branches share head loss and their flows add through the common pipe. Series segments carry equal flow and their losses add. Laminar transition, pressure-dependent valves, cavitation and pump dynamics are excluded.']);
schema('hydraulic-circuit','hydraulicCircuit','Hydraulic cylinder and directional valve',11,'Move a double-acting cylinder, switch the valve and inspect flow, force and relief-valve operation.',[s('direction','Directional valve','extend',[['extend','Extend: pump to cap side'],['retract','Retract: pump to rod side'],['neutral','Open-centre neutral: pump to tank']]),n('displacement','Pump displacement','cm³/rev',20,.1,1000),n('rpm','Pump speed','rpm',1500,1,5000),n('efficiency','Pump volumetric efficiency','fraction',.9,.1,1),n('bore','Cylinder bore','mm',100,1,1000),n('rod','Piston rod diameter','mm',50,.1,999),n('stroke','Full stroke','m',.5,.001,10),n('load','Load opposing selected movement','N',10000,0,1e6),n('friction','Constant opposing friction','N',500,0,1e5),n('relief','Relief-valve setting','bar',100,1,500),n('time','Elapsed time from starting end','s',1,0,600)],['Ideal fixed-displacement pump with supplied volumetric efficiency, incompressible fluid, zero return pressure and no line or valve pressure loss.','Each selected movement starts at its appropriate stroke end. Opposing load and friction are nonnegative; overrunning loads and counterbalance valves are excluded.','Cap and annulus areas differ, so extending and retracting speeds, forces and return flows differ. At or above required relief pressure the cylinder stalls. At full stroke all pump flow goes through relief.','The display gives pump hydraulic power, not shaft input power. Compressibility, acceleration, leakage at the actuator and pressure transients are excluded.']);
schema('rankine','rankine','Rankine steam power cycle',10,'Connect feed pump, boiler, steam turbine and condenser with local water-property states and an energy balance.',[n('boiler','Boiler absolute pressure','bar(a)',40,2,150),n('condenser','Condenser absolute pressure','bar(a)',.1,.05,2),n('temperature','Turbine inlet temperature','°C',400,150,600),n('turbineEfficiency','Turbine isentropic efficiency','fraction',.8,.3,1),n('pumpEfficiency','Pump hydraulic efficiency','fraction',.8,.3,1),n('flow','Steam mass flow','kg/s',1,.001,1000)],['Simple steady Rankine cycle: saturated liquid leaves the condenser, boiler pressure is constant, turbine inlet is superheated, condenser pressure is constant.','Water properties use the locally bounded IF97 Regions 1/2/4 adapter. No Region 3 or critical-region extrapolation is used.','Feed-pump work uses incompressible wp=vfΔp/ηp at condenser-liquid specific volume. The compressed-liquid outlet temperature/entropy is then recovered from Region 1 enthalpy.','Turbine h4=h3−ηt(h3−h4s), where s4s=s3. Lines between discrete states are diagram guides, not a detailed turbine or heat-exchanger process path. Pressure losses, heat leakage and generator losses are excluded.']);
schema('refrigeration-ph','refrigerationPH','R134a refrigeration pressure–enthalpy cycle',12,'Follow compressor, condenser, expansion valve and evaporator, with superheat and subcooling.',[n('evaporating','Evaporating saturation temperature','°C',-10,-25,10),n('condensing','Condensing saturation temperature','°C',40,20,55),n('superheat','Suction superheat','K',5,0,30),n('subcool','Condenser liquid subcooling','K',5,0,20),n('efficiency','Compressor isentropic efficiency','fraction',.75,.4,1),n('flow','Refrigerant mass flow','kg/s',.05,.001,10)],['Single-stage R134a cycle using local bounded CoolProp HEOS-generated tables, with interpolation. Temperatures, enthalpies and entropies share one reference convention.','The property table spans −30 to 60 °C saturation temperatures, 0–120 K superheat and 0–20 K subcooling. Unsupported compressor states are rejected rather than extrapolated.','Compression uses ηis=(h2s−h1)/(h2−h1), with s2s=s1. The expansion valve is isenthalpic, h4=h3, and this model requires its outlet inside the two-phase region.','Pressure is plotted on a linear absolute-pressure scale. State connections are guides. Pressure drops, heat leakage and compressor mechanical/electrical losses are excluded; mass-flow-based capacity is not equipment selection data.']);
const circuit=[count('nodes','Active nodes','4',3,6),count('branches','Active resistors','5',2,10),n('supply','Source voltage: node 2 relative to node 1','V',24,0,1000),n('probeA','Voltmeter positive node','',3,1,6),n('probeB','Voltmeter negative node','',1,1,6),n('ammeter','Ammeter resistor number','',1,1,10)];for(let i=1;i<=10;i++){const pair=[[2,3],[3,1],[2,4],[4,1],[3,4],[4,5],[5,1],[3,5],[5,6],[6,1]][i-1],extra={group:'Resistor '+i,...live('branches',Math.max(2,i),10)};circuit.push(n('a'+i,'First node number','',pair[0],1,6,extra),n('b'+i,'Second node number','',pair[1],1,6,extra),n('r'+i,'Resistance','Ω',100,.01,1e7,extra));}
schema('resistor-network','resistorNetwork','Kirchhoff circuit builder and meters',6,'Connect a resistor network and inspect ideal voltmeter and branch-ammeter readings.',circuit,['Steady DC, ideal source between node 2 and grounded node 1, positive finite resistors and ideal wires. Parallel duplicate pairs are replaced by their equivalent resistor rather than duplicated in the builder.','Unknown node voltages follow nodal Kirchhoff equations. Unconstrained floating nodes are rejected. Positive branch current flows from its first node to its second node.','The ideal voltmeter has infinite impedance and does not alter the circuit. The selected ammeter reads the current already flowing in a resistor branch; it does not create a short-circuit connection.','Power is checked against source input and resistor dissipation. Reactive components, wire resistance, source current limits and instrument protection are excluded.']);
schema('induction-motor','inductionMotor','Induction motor torque and slip',6,'Inspect a referred per-phase equivalent circuit, torque–speed characteristic, current and power balance.',[n('voltage','Supply line RMS voltage','V',400,1,20000),n('frequency','Supply frequency','Hz',50,1,400),n('poles','Number of poles','',4,2,16),s('connection','Stator winding connection','star',[['star','Star'],['delta','Delta']]),n('r1','Stator resistance per phase','Ω',.5,.001,100),n('x1','Stator leakage reactance','Ω',1,.001,100),n('r2','Referred rotor resistance','Ω',.3,.001,100),n('x2','Referred rotor leakage reactance','Ω',1,.001,100),n('xm','Magnetizing reactance','Ω',30,.1,10000),n('slip','Motoring slip','fraction',.04,0,1),n('load','Constant opposing load torque','N·m',80,0,1e5)],['Balanced sinusoidal steady state. All per-phase rotor parameters are referred to the stator; reactances are the entered values at the selected operating frequency. They are not automatically scaled when frequency changes.','The magnetizing branch jXm is in parallel with R2′/s+jX2′, after R1+jX1. Synchronous speed is 120f/poles rpm.','Electromagnetic torque is air-gap power divided by synchronous angular speed. Developed mechanical power is (1−s) times air-gap power, before mechanical losses. At zero slip the rotor branch is open.','Iron, stray, friction and windage losses, saturation and thermal dependence are excluded. The supplied load line is a comparison; changing the entered slip is not a dynamic acceleration simulation.']);
const unbalanced=[n('voltage','Source line-to-line RMS voltage','V',400,1,20000),n('frequency','Source frequency','Hz',50,1,400),s('neutral','Neutral connection','ideal',[['ideal','Ideal neutral'],['impedance','Neutral with supplied impedance'],['floating','No neutral conductor']]),n('rn','Neutral resistance','Ω',.5,0,10000,{when:{neutral:'impedance'}}),n('xn','Neutral reactance','Ω',0,-10000,10000,{when:{neutral:'impedance'}})];for(let i=1;i<=3;i++)unbalanced.push(n('r'+i,'Phase resistance','Ω',10*i,.01,10000,{group:'Phase '+['A','B','C'][i-1]}),n('x'+i,'Phase reactance: inductive positive','Ω',5*i,-10000,10000,{group:'Phase '+['A','B','C'][i-1]}));
schema('unbalanced-three-phase','unbalancedThreePhase','Unbalanced three-phase and neutral',6,'Change each star-connected load and compare neutral displacement, phase currents and power balance.',unbalanced,['Ideal balanced positive-sequence sinusoidal source, with three unequal linear star-connected R+jX load branches. RMS phasors use A=0°, B=−120°, C=+120°.','For a floating neutral, Vn=Σ(Vphase/Zphase)/Σ(1/Zphase). A finite neutral conductor adds its admittance to the denominator. An ideal neutral fixes Vn=0.','Current in each phase is (Vphase−Vn)/Zphase. Their phasor sum returns through the neutral when connected; it is zero at the floating load node.','Source active power equals load active power plus neutral resistive loss. Conductor phase impedances, harmonics, nonlinear loads, switching and protection are excluded.']);
schema('relative-motion','relativeMotion','Relative motion and closest approach',13,'Predict closest approach, then vary vessel courses and speeds and compare relative tracks.',[n('east','Initial target east offset','NM',4,-100,100),n('north','Initial target north offset','NM',6,-100,100),n('ownSpeed','Own speed over ground','kn',10,0,60),n('ownCourse','Own course over ground, true','°',0,0,360),n('targetSpeed','Target speed over ground','kn',8,0,60),n('targetCourse','Target course over ground, true','°',270,0,360),n('horizon','Displayed horizon','min',60,1,240)],['Flat local east–north geometry, constant course and speed over ground for both vessels. One knot is one nautical mile per hour.','Relative velocity is target velocity minus own velocity. Signed TCPA=−(r·vrel)/|vrel|². Future minimum range restricts time to t≥0. A past closest approach gives future CPA equal to current range.','Zero relative velocity has constant relative position and no unique CPA time. The displayed horizon limits the drawn track, not the analytical closest-approach calculation.','Educational geometry only: no AIS feed, manoeuvre prediction, collision-avoidance instruction or assessment of navigation rules.']);
const bearings=[count('count','Bearing observations','3',2,4),n('sigma','Independent bearing standard uncertainty','°',.5,0,5)];for(let i=1;i<=4;i++){const extra={group:'Landmark '+i,...live('count',Math.max(2,i),4)};bearings.push(n('x'+i,'Landmark east coordinate','NM',[5,0,-4,3][i-1],-100,100,extra),n('y'+i,'Landmark north coordinate','NM',[0,5,3,-4][i-1],-100,100,extra),n('bearing'+i,'Observed true bearing from vessel','°',[90,0,306.869897645844,143.130102354156][i-1],0,360,extra));}
schema('bearing-fix','bearingFix','Bearing fixes and observation uncertainty',13,'Intersect landmark bearing lines and inspect position sensitivity and a local uncertainty ellipse.',bearings,['Local Cartesian east–north coordinates in nautical miles. Bearings are true, clockwise from north, from the observer towards each known landmark.','Two bearing lines intersect; three or four inconsistent observations use an unweighted least-squares fit to perpendicular line residuals. Near-parallel geometry is rejected or highlighted.','Bearing errors are assumed independent, zero-mean Gaussian with the same supplied standard uncertainty. First-order covariance uses central numerical derivatives of the same least-squares estimator.','The plotted approximate 95% two-dimensional ellipse uses χ²2=.95 = 5.99146. It is a local linear approximation, not a guaranteed containment area. Landmark uncertainty, compass bias and geodetic curvature are excluded.']);
})(typeof window==='undefined'?globalThis:window);
